+// Sites (kitchens). Every location belongs to a site; batches, stock on hand,
+// cooking, alerts, stock value and stock-takes are scoped to the request's site.
+import { AppError } from "../errors.js";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** Set of location ids belonging to `site`. */
+export function siteLocationIds(store, site) {
+  return new Set((store.data.locations ?? []).filter((l) => l.site === site).map((l) => l.id));
+}
+
+/** Predicate matching batches in `site` (all batches when `site` is unset). */
+export function batchSiteFilter(store, site) {
+  if (site === undefined) return () => true;
+  const locs = siteLocationIds(store, site);
+  return (b) => locs.has(b.location);
+}
