+const ANNEX = { "X-Larder-Site": "annex" };
+
+test("unknown X-Larder-Site returns 400 with unknown_site", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "X-Larder-Site": "roof" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+});
+
+test("shared resources are visible in annex while stock and batches are scoped", async () => {
+  const { handle } = app();
+  const items = await handle({ path: "/items", headers: ANNEX });
+  assert.equal(items.status, 200);
+  assert.equal(items.body.length, 6);
+  assert.ok(items.body.every((i) => i.onHand === 0));
+
+  const item1 = await handle({ path: "/items/1", headers: ANNEX });
+  assert.equal(item1.status, 200);
+  assert.equal(item1.body.onHand, 0);
+  assert.deepEqual(item1.body.batches, []);
+
+  assert.deepEqual((await handle({ path: "/batches", headers: ANNEX })).body, []);
+  assert.equal((await handle({ path: "/batches/1", headers: ANNEX })).status, 404);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: ANNEX, body: { qty: 1 } })).status, 404);
+
+  assert.ok((await handle({ path: "/suppliers", headers: ANNEX })).body.length > 0);
+  assert.ok((await handle({ path: "/dishes", headers: ANNEX })).body.length > 0);
+  assert.equal((await handle({ path: "/recipes/1/cost", headers: ANNEX })).status, 200);
+});
+
+test("cooking, alerts and stock value only see the request's site", async () => {
+  const { handle, store } = app();
+  const beforeMain = JSON.stringify(store.data.batches);
+
+  // Annex has no stock yet: cooking fails and touches nothing in main.
+  const failCook = await handle({ method: "POST", path: "/recipes/2/cook", headers: ANNEX, body: { portions: 5 } });
+  assert.equal(failCook.status, 409);
+  assert.equal(JSON.stringify(store.data.batches), beforeMain);
+
+  // Annex stock value is 0 and expiring alerts exclude main batches.
+  assert.equal((await handle({ path: "/reports/stock-value", headers: ANNEX })).body.totalCents, 0);
+  const annexAlerts = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.deepEqual(annexAlerts.expiring, []);
+  assert.ok(annexAlerts.lowStock.some((i) => i.name === "flour" && i.qty === 0));
+
+  // Receive stock into annex-fridge (items 2, 3, 4 for recipe 2: bechamel).
+  const created = await handle({
+    method: "POST",
+    path: "/orders",
+    headers: ANNEX,
+    body: { supplierId: 2, lines: [{ itemId: 2, qty: 4 }, { itemId: 3, qty: 1 }, { itemId: 4, qty: 1 }] },
+  });
+  await handle({ method: "POST", path: `/orders/${created.body.id}/send`, headers: ANNEX });
+  const received = await handle({
+    method: "POST",
+    path: `/orders/${created.body.id}/receive`,
+    headers: ANNEX,
+    body: {
+      lots: [
+        { lot: "AX-1", expires: "2026-10-30", location: "annex-fridge" },
+        { lot: "AX-2", expires: "2026-12-30", location: "annex-fridge" },
+        { lot: "AX-3", expires: "2027-01-30", location: "annex-fridge" },
+      ],
+    },
+  });
+  assert.equal(received.status, 200);
+
+  // Main still doesn't see annex batches; annex sees its own batches, stock value and alerts.
+  assert.equal((await handle({ path: "/items/2" })).body.onHand, 10);
+  assert.equal((await handle({ path: "/items/2", headers: { "x-larder-site": "annex" } })).body.onHand, 4);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: ANNEX })).body.totalCents, 4 * 129 + 945 + 85);
+  assert.deepEqual((await handle({ path: "/alerts", headers: ANNEX })).body.expiring.map((b) => b.lot), ["AX-1"]);
+
+  // Cooking in annex consumes only annex batches.
+  const cooked = await handle({ method: "POST", path: "/recipes/2/cook", headers: ANNEX, body: { portions: 5 } });
+  assert.equal(cooked.status, 200);
+  assert.equal((await handle({ path: "/items/2", headers: ANNEX })).body.onHand, 3);
+  assert.equal((await handle({ path: "/items/2" })).body.onHand, 10);
